def add_job_change_item_drops(
    apps,
    schema_editor,
):

    Item = apps.get_model(
        "inventory",
        "Item",
    )

    FloorDropItem = apps.get_model(
        "battle",
        "FloorDropItem",
    )

    job_change_items = Item.objects.filter(
        name__in=JOB_CHANGE_ITEM_NAMES,
    )

    # 1～12層すべてに登録
    for floor in range(1, 13):

        for item in job_change_items:

            FloorDropItem.objects.update_or_create(
                floor=floor,
                item=item,
                defaults={
                    "drop_weight": 100,
                },
            )


def remove_job_change_item_drops(
    apps,
    schema_editor,
):

    Item = apps.get_model(
        "inventory",
        "Item",
    )

    FloorDropItem = apps.get_model(
        "battle",
        "FloorDropItem",
    )

    item_ids = Item.objects.filter(
        name__in=JOB_CHANGE_ITEM_NAMES,
    ).values_list(
        "id",
        flat=True,
    )

    FloorDropItem.objects.filter(
        floor__gte=1,
        floor__lte=12,
        item_id__in=item_ids,
    ).delete()


